    const [repItem, setRepItem] = useState("");
    const [from, setFrom] = useState("");
    const [to, setTo] = useState("");
    const loadItems = () => GET("/admin/welfare-items").then(setItems).catch(() => { });
    const loadPlaces = () => GET("/admin/welfare-places").then(setPlaces).catch(() => { });
    useEffect(() => { loadItems(); loadPlaces(); }, []);
    const saveItem = async () => { if (!newItem.title.trim())
        return; await SEND("POST", "/admin/welfare-items", newItem); setNewItem({ title: "", description: "" }); loadItems(); };
    const toggleItem = async (it) => { await SEND("POST", "/admin/welfare-items", { ...it, is_active: it.is_active ? 0 : 1 }); loadItems(); };
    const delItem = async (id) => { if (!confirm("حذف این نوع رفاهیت؟"))
        return; await SEND("DELETE", "/admin/welfare-items/" + id); loadItems(); };
    const savePlace = async () => { if (!newPlace.title.trim())
        return; await SEND("POST", "/admin/welfare-places", newPlace); setNewPlace({ title: "", address: "", phone: "" }); loadPlaces(); };
    const togglePlace = async (pl) => { await SEND("POST", "/admin/welfare-places", { ...pl, is_active: pl.is_active ? 0 : 1 }); loadPlaces(); };
    const delPlace = async (id) => { if (!confirm("حذف این مکان؟"))
        return; await SEND("DELETE", "/admin/welfare-places/" + id); loadPlaces(); };
    const lookup = async () => {
        const n = nid.replace(/\D/g, "");
        if (n.length < 8) {
            setMsg("کد ملی معتبر وارد کنید");
            return;
        }
        try {
            const r = await GET("/search?national_id=" + n);
            if (r.type === "driver") {
                setDriver(r.driver);
                setMsg("");
            }
            else
                setMsg("راننده یافت نشد");
        }
        catch (e) {
            setDriver(null);
            setMsg("راننده‌ای با این کد ملی یافت نشد");
        }
    };
    const grant = async () => {
        const n = nid.replace(/\D/g, "");
        if (n.length < 8) {
            setMsg("کد ملی معتبر وارد کنید");
            return;
        }
        if (!grantItem) {
            setMsg("نوع رفاهیت را انتخاب کنید");
            return;
        }
        try {
            const r = await SEND("POST", "/admin/welfare-grants", { item_id: +grantItem, place_id: grantPlace ? +grantPlace : null, driver_national_id: n, count: +count, note, granted_jdate: gdate });
            setMsg("✓ رفاهیت برای " + (r.driver_name || "راننده") + " ثبت شد");
            setNid("");
            setDriver(null);
            setCount(1);
            setNote("");
            setGrantItem("");
            setGrantPlace("");
        }
        catch (e) {
            setMsg(e.message || "خطا در ثبت");
        }
    };
