        setBusy("migrate");
        setMigResult(null);
        let totalMig = 0, rounds = 0;
        try {
            let more = true;
            while (more && rounds < 100) {
                const d = await SEND("POST", "/admin/migrate-images", { limit: 100 });
                rounds++;
                for (const k in (d.report || {})) {
                    const r = d.report[k];
                    if (r && typeof r === "object" && r.migrated)
                        totalMig += r.migrated;
                }
                more = d.more;
                setMigResult({ running: true, total: totalMig, rounds });
            }
            setMigResult({ running: false, total: totalMig, rounds, done: true });
        }
        catch (e) {
            setMigResult({ running: false, error: e.message, total: totalMig });
        }
