    const loadLine = (id) => { setLineId(id); if (!id) {
        db.smsDrivers().then(d => setDrivers(d || [])).catch(() => { });
        return;
    } db.smsDriversByLine(id).then(d => setDrivers(d || [])).catch(() => { }); };
    const toggle = (id) => setSel(s => ({ ...s, [id]: !s[id] }));
    const chosen = drivers.filter(d => sel[d.id]);
